import sys
from typing import List

class Solution:
    def finishTime(self, n: int, edges: List[List[int]], baseTime: List[int]) -> int:
        sys.setrecursionlimit(300000)
        children = [[] for _ in range(n)]
        for u, v in edges:
            children[u].append(v)

        def dfs(u: int) -> int:
            if not children[u]:
                return baseTime[u]
            mn = mx = dfs(children[u][0])
            for c in children[u][1:]:
                f = dfs(c)
                mn = min(mn, f)
                mx = max(mx, f)
            return mx + (mx - mn) + baseTime[u]

        return dfs(0)

