class Solution {
    private List<List<Integer>> ch;
    private int[] bt;

    public long finishTime(int n, int[][] edges, int[] baseTime) {
        ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int[] e : edges) ch.get(e[0]).add(e[1]);
        bt = baseTime;
        return dfs(0);
    }

    private long dfs(int u) {
        if (ch.get(u).isEmpty()) return bt[u];
        long mn = Long.MAX_VALUE, mx = Long.MIN_VALUE;
        for (int c : ch.get(u)) {
            long f = dfs(c);
            mn = Math.min(mn, f);
            mx = Math.max(mx, f);
        }
        return mx + (mx - mn) + bt[u];
    }
}

