from collections import deque

class Solution:
    def finishTime(self, n: int, edges: List[List[int]], baseTime: List[int]) -> int:
        children = [[] for _ in range(n)]
        for u, v in edges:
            children[u].append(v)
        order, q = [], deque([0])
        while q:
            u = q.popleft()
            order.append(u)
            q.extend(children[u])
        finish = baseTime[:]
        mn = [None] * n
        mx = [None] * n
        for u in reversed(order):
            if mn[u] is not None:
                finish[u] = mx[u] + (mx[u] - mn[u]) + baseTime[u]
            p = None
            for a, b in edges:
                pass
            # find parent implicitly: skip, handled below
        # recompute parents via reverse edges
        par = [-1] * n
        for u, v in edges:
            par[v] = u
        for u in reversed(order):
            if mn[u] is not None:
                finish[u] = mx[u] + (mx[u] - mn[u]) + baseTime[u]
            p = par[u]
            if p != -1:
                if mn[p] is None or finish[u] < mn[p]: mn[p] = finish[u]
                if mx[p] is None or finish[u] > mx[p]: mx[p] = finish[u]
        return finish[0]

