#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    long long finishTime(int n, vector<vector<int>>& edges, vector<int>& baseTime) {
        vector<vector<int>> ch(n);
        vector<int> par(n, -1);
        for (auto& e : edges) { ch[e[0]].push_back(e[1]); par[e[1]] = e[0]; }
        vector<int> order;
        order.reserve(n);
        vector<int> stk = {0};
        while (!stk.empty()) {
            int u = stk.back(); stk.pop_back();
            order.push_back(u);
            for (int c : ch[u]) stk.push_back(c);
        }
        vector<long long> fin(baseTime.begin(), baseTime.end());
        vector<long long> mn(n, LLONG_MAX), mx(n, LLONG_MIN);
        vector<char> hasChild(n, 0);
        for (auto& e : edges) hasChild[e[0]] = 1;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            if (hasChild[u]) fin[u] = mx[u] + (mx[u] - mn[u]) + baseTime[u];
            int p = par[u];
            if (p != -1) { mn[p] = min(mn[p], fin[u]); mx[p] = max(mx[p], fin[u]); }
        }
        return fin[0];
    }
};

