class Solution {
    public long finishTime(int n, int[][] edges, int[] baseTime) {
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        int[] par = new int[n];
        Arrays.fill(par, -1);
        boolean[] hasChild = new boolean[n];
        for (int[] e : edges) {
            ch.get(e[0]).add(e[1]);
            par[e[1]] = e[0];
            hasChild[e[0]] = true;
        }
        int[] order = new int[n];
        int idx = 0;
        Deque<Integer> stk = new ArrayDeque<>();
        stk.push(0);
        while (!stk.isEmpty()) {
            int u = stk.pop();
            order[idx++] = u;
            for (int c : ch.get(u)) stk.push(c);
        }
        long[] fin = new long[n];
        for (int i = 0; i < n; i++) fin[i] = baseTime[i];
        long[] mn = new long[n], mx = new long[n];
        Arrays.fill(mn, Long.MAX_VALUE);
        Arrays.fill(mx, Long.MIN_VALUE);
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            if (hasChild[u]) fin[u] = mx[u] + (mx[u] - mn[u]) + baseTime[u];
            int p = par[u];
            if (p != -1) { mn[p] = Math.min(mn[p], fin[u]); mx[p] = Math.max(mx[p], fin[u]); }
        }
        return fin[0];
    }
}

